To shuffle a list in C# deterministically, you can use the Fisher-Yates algorithm. This algorithm ensures that the list is shuffled in a way that is reproducible given the same seed. Here's how you can implement this:

```csharp
using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        List<int> numbers = new List<int> { 1, 2, 3, 4, 5 };
        ShuffleListDeterministically(numbers, 12345);
        Console.WriteLine(string.Join(", ", numbers));
    }

    static void ShuffleListDeterministically(List<int> list, int seed)
    {
        Random random = new Random(seed);
        int n = list.Count;
        while (n > 1)
        {
            n--;
            int k = random.Next(n + 1);
            int temp = list[k];
            list[k] = list[n];
            list[n] = temp;
        }
    }
}
```

