To write a C# method that returns the top n frequent words in a paragraph, you can follow these steps:

1. Split the paragraph into words.
2. Count the frequency of each word.
3. Sort the words by frequency in descending order.
4. Return the top n words.

Here's a sample implementation:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class WordFrequencyAnalyzer
{
    public static List<string> GetTopNFrequentWords(string paragraph, int n)
    {
        // Split the paragraph into words
        var words = paragraph.Split(new char[] { ' ', '.', ',', '!', '?' }, StringSplitOptions.RemoveEmptyEntries);

        // Count the frequency of each word
        var wordCounts = words.GroupBy(word => word)
                               .ToDictionary(group => group.Key, group => group.Count());

        // Sort the words by frequency in descending order
        var sortedWords = wordCounts.OrderByDescending(pair => pair.Value)
                                   .ThenBy(pair => pair.Key)
                                   .Take(n)
                                   .Select(pair => pair.Key)
                                   .ToList();

        return sortedWords;
    }
}

// Example usage:
class Program
{
    static void Main()
    {
        string paragraph = "The quick brown fox jumps over the lazy dog. The dog barks, the fox runs.";
        int n = 3;
        var topNWords = WordFrequencyAnalyzer.GetTopNFrequentWords(paragraph, n);
        foreach (var word in topNWords)
        {
            Console.WriteLine(word);
        }
    }
}
```

