    // Finds the longest run of the same character in the given string.
    // Returns the longest run and its length.
    public static Tuple<string, int> FindLongestRun(string input)
    {
        if (string.IsNullOrEmpty(input)) return Tuple.Create("", 0);

        int maxLength = 1;
        int currentLength = 1;
        string longestRun = input[0].ToString();

        for (int i = 1; i < input.Length; i++)
        {
            if (input[i] == input[i - 1])
            {
                currentLength++;
