Certainly! Converting a Roman numeral to an integer in C# can be done by mapping each Roman numeral character to its corresponding integer value and then summing these values. Here's a method that does this:

```csharp
using System;

public class RomanToIntegerConverter
{
    public static int RomanToInt(string roman)
    {
        if (string.IsNullOrEmpty(roman))
        {
            throw new ArgumentException("Input string cannot be null or empty.", nameof(roman));
        }

        var romanValues = new Dictionary<char, int>
        {
            {'I', 1},
            {'V', 5},
            {'X', 10},
            {'L', 50},
            {'C', 100},
            {'D', 500},
            {'M', 1000}
        };

        int result = 0;
        int prevValue = 0;

        for (int i = roman.Length - 1; i >= 0; i--)
        {
            int currentValue = romanValues[roman[i]];

            if (currentValue < prevValue)
            {
                result -= currentValue;
            }
            else
            {
                result += currentValue;
            }

            prevValue = currentValue;
        }

        return result;
    }

    public static void Main(string[] args)
    {
        string romanNumeral = "MCMXCIV";
        int integerValue = RomanToInt(romanNumeral);
        Console.WriteLine($"The integer value of {romanNumeral} is {integerValue}.");
    }
}
```

